      "paragraphs": [
        "[Dē Trimalchiōne in balneō]",
        "27 Nōs interim vestītī errāre coepimus, immō iocārī magis et circulīs accēdere, cum subitō vidēmus senem calvum, tunicā vestītum russeā, inter puerōs capillātōs lūdentem pilā. Nec tam puerī nōs, quamquam erat operae pretium, ad spectāculum dūxerant, quam ipse pater familiās, quī soleātus pilā prasinā exercēbātur. Nec amplius eam repetēbat quae terram contigerat, sed follem plēnum habēbat servus sufficiēbatque lūdentibus. Notāvimus etiam rēs novās: nam duo spadōnēs in diversā parte circulī stābant, quōrum alter matellam tenēbat argenteam, alter numerābat pilās, nōn quidem eās quae inter manūs lūsū expellente vibrābant, sed eās quae in terram dēcidēbant.",
        "Cum hās ergō mīrārēmur lautitiās, accurrit Menelāus: “Hic est, inquit, apud quem cubitum pōnētis, et quidem iam prīncipium cēnae vidētis. Et iam nōn loquēbātur Menelāus cum Trimalchiō digitōs concrepuit, ad quod signum matellam spadō lūdentī subiēcit. Exonerātā ille vēsīca aquam poposcit ad manūs, digitōsque paululum adspersōs in capite puerī tersit.",
        "28 Longum erat singula excipere. Itaque intrāvimus balneum, et sūdōre calfactī mōmentō temporis ad frīgidam exīmus."
      ],
