      "title": "Ganymēdēs dē annōnā, dē aedīlibus, dē dīs īrātīs",
      "paragraphs": [
        "[Ganymēdēs dē annōnā, dē aedīlibus, dē dīs īrātīs]",
        "44 Haec Philerōs dīxit, illa Ganymēdēs: “Nārrātis quod nec ad caelum nec ad terram pertinet, cum interim nēmō cūrat quid annōna mordet. Nōn meherculēs hodiē buccam pānis invenīre potuī. Et quōmodo siccitās persevērat! Iam annum ēsurītiō fuit. Aedīlēs male ēveniat, quī cum pistōribus collūdunt: 'Servā mē, servābō tē.' Itaque populus minūtus labōrat; Nam istī māiōrēs māxillae semper Sāturnālia agunt. Ō sī habērēmus illōs leōnēs, quōs ego hīc invēnī, cum prīmum ex Asiā vēnī. Illud erat vīvere Meminī Safinium; tunc habitābat ad arcum veterem, mē puerō: Piper, nōn homō. Is quācumque ībat, terram adūrēbat. Sed rēctus, sed certus, amīcus amīcō, cum quō audācter possēs in tenebrīs micāre. In Cūriā autem quōmodo singulōs pīlābat. Nec schēmās loquēbātur sed dīrēctum. Cum ageret porrō in forō, sīc illīus Vōx crēscēbat tamquam tubā. Nec sūdāvit umquam nec expuit; putō enim nesciō quid Asiadis habuisse. Et quam benignus resalūtāre, nōmina omnium reddere, tamquam ūnus dē nōbīs! Itaque illō tempore annōna prō lutō erat. Asse pānem quem ēmissēs, nōn potuissēs cum alterō dēvorāre. Nunc oculum būblum vīdī māiōrem. Heu heu, Quotīdiē pēius! Haec colōnia retrōversus crēscit tamquam cōda vitulī. Sed quārē nōs Habēmus aedīlem trium caunīārum, quī sibi māvult assem quam vītam nostram? Itaque domī"
      ],
