      "id": "cena-27",
      "latinTitle": "SECTIŌNĒS 44–45",
      "title": "Echīōn dē Iūlī mūnere gladiātōriō et dē fīliolō suō",
      "paragraphs": [
        "gaudet, plūs in diē nummōrum accipit quam alter patrimōnium habet. Iam sciō unde accēperit dēnāriōs mīlle aureōs. Sed sī nōs coleōs habērēmus, nōn tantum sibi placēret. Nunc populus est domī leōnēs, forās vulpēs. Quod ad mē attinet, iam pannōs meōs comēdī, et sī persevērat haec annōna, casulās meās vēndam. Quid enim futūrum est, sī nec diī nec hominēs huius colōniae miserentur? Ita meōs frūnīscar, ut ego putō omnia illa ā diibus fierī. Nēmō enim caelum caelum putat, nēmō iēiūnium servat, nēmō Iovem pilī facit, sed omnēs opertīs oculīs bona sua computant. Anteā stolātae ībant nūdīs pedibus in clīvum, passīs capillīs, mentibus pūrīs, et Iovem aquam exōrābant. Itaque statim urceātim plovēbat: aut tunc aut numquam, et omnēs rīdēbant ūdī tamquam mūrēs. Itaque diī pedēs lānātōs habent, quia nōs religiōsī nōn sumus. Agrī iacent.",
        "[Echīōn dē Iūlī mūnere gladiātōriō et dē fīliolō suō]",
        "45 — Ōrō tē, inquit Echīōn centōnārius, melius loquere. 'Modo sīc, modo sīc', inquit rūsticus: varium porcum perdiderat. Quod hodiē nōn est, crās erit: sīc vīta trūditur. Nōn meherculēs patria melior dīcī potest, sī hominēs habēret. Sed labōrat hōc tempore, nec haec sōla. Nōn dēbēmus dēlicātī esse; ubīque medius caelus est. Tū sī aliubī fuerīs, dīcēs hīc porcōs coctōs ambulāre."
      ],
