      "paragraphs": [
        "tanquam vīvum. “Nam vīnum quidem in vīnārium iussit īnfundī et: ” Putāte vōs, inquit, ad parentālia mea invītātōs esse“.",
        "Ībat rēs ad summam nauseam, cum Trimalchiō ēbrietāte turpissimā gravis novum ācroāma, cornicinēs, in triclīnium iussit addūcī, fultusque cervīcālibus multīs extendit sē suprā torum extrēmum et: “Fingite mē, inquit, mortuum esse. Dīcite aliquid bellī.” Cōnsonuēre cornicinēs fūnebrī strepitū. Ūnus praecipuē servus libitīnāriī illīus, quī inter hōs honestissimus erat, tam valdē intonuit, ut tōtam concitāret vīcīniam.",
        "Itaque vigilēs, quī cūstōdiēbant vīcīnam regiōnem, ratī ārdēre Trimalchiōnis domum, effrēgērunt iānuam subitō et cum aquā secūribusque tumultuārī suō iūre coepērunt. Nōs occāsiōnem opportūnissimam nactī Agamemnonī verba dedimus, raptimque tam plānē quam ex incendiō fūgimus."
      ],
